import{_ as s,o as n,c as e,a4 as p}from"./chunks/framework.75w6ylfU.js";const l="/XIAOHUANG_BLOG/assets/image-20250905155834618.B8ZF0Fg4.png",i="/XIAOHUANG_BLOG/assets/image-20250905155949678.CvaUGDHb.png",t="/XIAOHUANG_BLOG/assets/image-20250905160115901.DJo77OjZ.png",o="/XIAOHUANG_BLOG/assets/image-20250905160239330.Bu2J6BFx.png",c="/XIAOHUANG_BLOG/assets/image-20250905160541502.DAUZFb05.png",r="/XIAOHUANG_BLOG/assets/image-20250905160631573.Em9yPL1B.png",d="/XIAOHUANG_BLOG/assets/image-20250905160751388.B52ISZ9o.png",u="/XIAOHUANG_BLOG/assets/image-20250905160840013.DyVyphsm.png",h="/XIAOHUANG_BLOG/assets/image-20230427154146879.BywVRadV.png",g="/XIAOHUANG_BLOG/assets/image-20230427154419005.D6F7m8JM.png",m="/XIAOHUANG_BLOG/assets/3.7.2RQT%E5%B7%A5%E5%85%B7%E7%AE%B1.CCEqtGP3.gif",b="/XIAOHUANG_BLOG/assets/3.7.2RQT%E5%B7%A5%E5%85%B7%E7%AE%B1topic.4sBfZfKX.gif",_="/XIAOHUANG_BLOG/assets/3.7.2RQT%E5%B7%A5%E5%85%B7%E7%AE%B1service-1698722363522-4.BAMZiD5D.gif",v="/XIAOHUANG_BLOG/assets/3.7.2RQT%E5%B7%A5%E5%85%B7%E7%AE%B1param.Bx76qy_l.gif",R=JSON.parse('{"title":"ROS2时间相关API","description":"","frontmatter":{},"headers":[],"relativePath":"docs/软件资料/编程资料/ROS2基础/ROS2详细笔记/Part4_ROS2API.md","filePath":"docs/软件资料/编程资料/ROS2基础/ROS2详细笔记/Part4_ROS2API.md"}'),k={name:"docs/软件资料/编程资料/ROS2基础/ROS2详细笔记/Part4_ROS2API.md"};function y(q,a,f,x,w,z){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="ros2时间相关api" tabindex="-1">ROS2时间相关API <a class="header-anchor" href="#ros2时间相关api" aria-label="Permalink to &quot;ROS2时间相关API&quot;">​</a></h1><h2 id="时间相关api简介" tabindex="-1">时间相关API简介 <a class="header-anchor" href="#时间相关api简介" aria-label="Permalink to &quot;时间相关API简介&quot;">​</a></h2><p>ros2涉及时间相关的API有Rate，Time，Duration，Time与Duration的运算等，下面分别讲解。</p><h2 id="实现ros2时间与定时功能" tabindex="-1">实现ROS2时间与定时功能 <a class="header-anchor" href="#实现ros2时间与定时功能" aria-label="Permalink to &quot;实现ROS2时间与定时功能&quot;">​</a></h2><ul><li>首先，创建一个功能包，用来存放相关的程序文件</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 pkg create learning_time --build-type ament_python --dependencies rclpy</span></span></code></pre></div><h3 id="使用rate实现定频率运行" tabindex="-1">使用Rate实现定频率运行 <a class="header-anchor" href="#使用rate实现定频率运行" aria-label="Permalink to &quot;使用Rate实现定频率运行&quot;">​</a></h3><p>ROS2 中还提供了create_rate函数，用于<strong>控制循环执行频率</strong>的工具，其核心作用是让一段代码按照<strong>固定频率周期性执行</strong>，<code>Rate</code> 通过控制循环的 “休眠时间” 来保证循环执行频率的稳定性。<strong>切记</strong>，<code>Rate</code>一般不能直接用于主线程，否则会永久阻塞回调事件，一般只用于带有多线程回调的程序或子线程中使用。</p><p>具体工作原理：</p><ol><li>记录每次循环开始的时间；</li><li>执行循环内的代码；</li><li>计算当前循环实际耗时与 “目标间隔时间” 的差值；</li><li>自动休眠对应的差值时间，确保从一次循环开始到下一次循环开始的间隔严格等于 “目标间隔”（如 100 毫秒）。</li></ol><p>虽然 <code>Rate</code> 和 <code>Timer</code> 都能实现周期性执行，但适用场景不同：</p><table tabindex="0"><thead><tr><th>特性</th><th><code>Rate</code></th><th><code>Timer</code></th></tr></thead><tbody><tr><td>实现方式</td><td>基于循环内主动休眠（阻塞当前线程）</td><td>基于回调函数（非阻塞，由 ROS 2 事件循环触发）</td></tr><tr><td>适用场景</td><td>适用于需要在<strong>同一线程</strong>内按固定频率执行的循环（如主控制逻辑）</td><td>适用于需要<strong>异步执行</strong>的周期性任务（不阻塞主线程）</td></tr><tr><td>灵活性</td><td>循环内可直接控制流程（如 break 退出）</td><td>需通过标志位等方式控制回调执行</td></tr></tbody></table><p>以下是 <code>Rate</code> 的基本用法，实现一个每秒执行 2 次的循环：</p><ul><li>功能包中新建一个文件rate_demo.py</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import rclpy</span></span>
<span class="line"><span>from rclpy.node import Node</span></span>
<span class="line"><span>import threading</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class RateExampleNode(Node):</span></span>
<span class="line"><span>    def __init__(self):</span></span>
<span class="line"><span>        super().__init__(&quot;rate_example_node&quot;)</span></span>
<span class="line"><span>        self.get_logger().info(&quot;Rate 示例节点启动&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    def run_loop(self):</span></span>
<span class="line"><span>        # 使用节点的create_rate()创建2Hz的Rate</span></span>
<span class="line"><span>        rate = self.create_rate(2)</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        count = 0</span></span>
<span class="line"><span>        try:</span></span>
<span class="line"><span>            while rclpy.ok():</span></span>
<span class="line"><span>                self.get_logger().info(f&quot;循环执行 {count} 次&quot;)</span></span>
<span class="line"><span>                count += 1</span></span>
<span class="line"><span>                rate.sleep()  # 休眠到下一个周期（0.5秒）</span></span>
<span class="line"><span>        except KeyboardInterrupt:</span></span>
<span class="line"><span>            self.get_logger().info(&quot;循环被中断&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def main(args=None):</span></span>
<span class="line"><span>    rclpy.init(args=args)</span></span>
<span class="line"><span>    node = RateExampleNode()</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    # 创建线程运行循环（避免阻塞主线程）</span></span>
<span class="line"><span>    loop_thread = threading.Thread(target=node.run_loop)</span></span>
<span class="line"><span>    loop_thread.start()</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    # 主线程执行spin，维持ROS 2节点运行</span></span>
<span class="line"><span>    try:</span></span>
<span class="line"><span>        rclpy.spin(node)</span></span>
<span class="line"><span>    except KeyboardInterrupt:</span></span>
<span class="line"><span>        pass</span></span>
<span class="line"><span>    finally:</span></span>
<span class="line"><span>        loop_thread.join()  # 等待线程结束</span></span>
<span class="line"><span>        node.destroy_node()</span></span>
<span class="line"><span>        rclpy.shutdown()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    main()</span></span></code></pre></div><ul><li>配置对应的setup.py配置文件，在console_scripts中添加</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39;rate_demo=learning_time.rate_demo:main&#39;</span></span></code></pre></div><img src="`+l+`" alt="image-20250905155834618" style="zoom:50%;"><ul><li>编译功能包</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>colcon build --packages-select learning_time</span></span></code></pre></div><ul><li>刷新工作空间环境并运行节点</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> source ./install/setup.bash</span></span>
<span class="line"><span>ros2 run learning_time rate_demo</span></span></code></pre></div><img src="`+i+`" alt="image-20250905155949678" style="zoom:50%;"><h3 id="使用timer定时器实现定频率运行" tabindex="-1">使用Timer定时器实现定频率运行 <a class="header-anchor" href="#使用timer定时器实现定频率运行" aria-label="Permalink to &quot;使用Timer定时器实现定频率运行&quot;">​</a></h3><ul><li>Timer用于创建一个定时触发的定时器来执行一些周期性任务</li><li>示例：创建两个定时器一个1秒执行一次打印执行次数，一个0.5秒执行一次打印当前时间</li><li>新建一个程序文件Timer_demo.py</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import rclpy</span></span>
<span class="line"><span>from rclpy.node import Node</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class TimerDemoNode(Node):</span></span>
<span class="line"><span>    def __init__(self):</span></span>
<span class="line"><span>        super().__init__(&#39;timer_demo_node&#39;)</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        # 计数器，用于演示定时器执行次数</span></span>
<span class="line"><span>        self.counter = 0</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        # 创建定时器：每1秒执行一次callback函数</span></span>
<span class="line"><span>        self.timer = self.create_timer(1.0, self.timer_callback)</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        # 创建一个更快的定时器：每0.5秒执行一次</span></span>
<span class="line"><span>        self.fast_timer = self.create_timer(0.5, self.fast_timer_callback)</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        self.get_logger().info(&quot;定时器节点已启动&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    def timer_callback(self):</span></span>
<span class="line"><span>        &quot;&quot;&quot;1秒定时器回调函数&quot;&quot;&quot;</span></span>
<span class="line"><span>        self.counter += 1</span></span>
<span class="line"><span>        current_time = self.get_clock().now()</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        # 打印当前时间和计数器值</span></span>
<span class="line"><span>        self.get_logger().info(</span></span>
<span class="line"><span>            f&quot;[1秒定时器] 第 {self.counter} 次执行，当前时间: {current_time.seconds_nanoseconds()}&quot;</span></span>
<span class="line"><span>        )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    def fast_timer_callback(self):</span></span>
<span class="line"><span>        &quot;&quot;&quot;0.5秒定时器回调函数&quot;&quot;&quot;</span></span>
<span class="line"><span>        # 打印当前时间戳（纳秒）</span></span>
<span class="line"><span>        self.get_logger().info(</span></span>
<span class="line"><span>            f&quot;[0.5秒定时器] 当前时间戳: {self.get_clock().now().nanoseconds}&quot;</span></span>
<span class="line"><span>        )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def main(args=None):</span></span>
<span class="line"><span>    # 初始化ROS 2</span></span>
<span class="line"><span>    rclpy.init(args=args)</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    # 创建节点</span></span>
<span class="line"><span>    node = TimerDemoNode()</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    # 运行节点</span></span>
<span class="line"><span>    rclpy.spin(node)</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    # 关闭ROS 2</span></span>
<span class="line"><span>    node.destroy_node()</span></span>
<span class="line"><span>    rclpy.shutdown()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if __name__ == &#39;__main__&#39;:</span></span>
<span class="line"><span>    main()</span></span></code></pre></div><ul><li>配置对应的setup.py配置文件，在console_scripts中添加</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39;Timer_demo=learning_time.Timer_demo:main&#39;</span></span></code></pre></div><img src="`+t+`" alt="image-20250905160115901" style="zoom:50%;"><ul><li>编译功能包</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>colcon build --packages-select learning_time</span></span></code></pre></div><ul><li>刷新工作空间环境并运行节点</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source ./install/setup.bash</span></span>
<span class="line"><span>ros2 run learning_time Timer_demo</span></span></code></pre></div><img src="`+o+`" alt="image-20250905160239330" style="zoom:50%;"><ul><li>可以看出定时器按照设定的定时时间触发，在各自的回调函数中打印对应的日志信息</li></ul><h3 id="使用get-clock获取当前时刻时间" tabindex="-1">使用get_clock获取当前时刻时间 <a class="header-anchor" href="#使用get-clock获取当前时刻时间" aria-label="Permalink to &quot;使用get_clock获取当前时刻时间&quot;">​</a></h3><ul><li>get_clock函数可以用来获取到时钟对象，再通过()方法获取到当前时刻时间</li><li>新建程序文件get_clock_demo.py,填入以下示例程序：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import rclpy</span></span>
<span class="line"><span>from rclpy.node import Node</span></span>
<span class="line"><span>from rclpy.time import Time</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class TimeExampleNode(Node):</span></span>
<span class="line"><span>    def __init__(self):</span></span>
<span class="line"><span>        super().__init__(&quot;time_example_node&quot;)</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        # 获取节点的时钟对象（默认使用系统时钟）</span></span>
<span class="line"><span>        self.clock = self.get_clock()</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>        # 获取当前时间（返回Time对象）</span></span>
<span class="line"><span>        current_time = self.clock.now()</span></span>
<span class="line"><span>        self.get_logger().info(f&quot;当前时间：{current_time}&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def main(args=None):</span></span>
<span class="line"><span>    rclpy.init(args=args)</span></span>
<span class="line"><span>    node = TimeExampleNode()</span></span>
<span class="line"><span>    rclpy.spin_once(node)  # 运行一次节点</span></span>
<span class="line"><span>    node.destroy_node()</span></span>
<span class="line"><span>    rclpy.shutdown()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    main()</span></span></code></pre></div><ul><li>配置对应的setup.py配置文件，在console_scripts中添加</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39;get_clock_demo=learning_time.get_clock_demo:main&#39;</span></span></code></pre></div><img src="`+c+`" alt="image-20250905160541502" style="zoom:50%;"><ul><li>编译功能包</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>colcon build --packages-select learning_time</span></span></code></pre></div><ul><li>刷新工作空间环境并运行节点</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source ./install/setup.bash</span></span>
<span class="line"><span>ros2 run learning_time get_clock_demo</span></span></code></pre></div><img src="`+r+`" alt="image-20250905160631573" style="zoom:67%;"><h3 id="使用duration计算时间间隔" tabindex="-1">使用Duration计算时间间隔 <a class="header-anchor" href="#使用duration计算时间间隔" aria-label="Permalink to &quot;使用Duration计算时间间隔&quot;">​</a></h3><p>Time 与 Duration</p><ul><li><strong><code>Time</code><strong>类在ros中用于表示一个具体的</strong>时间点</strong>（如 &quot;2023-10-01 12:00:00&quot;），通常用于标记事件发生的<strong>时刻</strong>。</li><li><strong><code>Duration</code><strong>类表示两个时间点之间的</strong>间隔</strong>（如 &quot;5 秒&quot;），用于计算时间差或延迟。</li><li>**示例：**Time 以及 Duration 应用</li><li>创建一个新的程序文件TimeDuration_demo.py</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import rclpy</span></span>
<span class="line"><span>from rclpy.time import Time</span></span>
<span class="line"><span>from rclpy.duration import Duration</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def main():</span></span>
<span class="line"><span>    rclpy.init()</span></span>
<span class="line"><span>    node = rclpy.create_node(&quot;time_opt_node&quot;)</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>    #time类的使用方法，创建‘时间点、时刻’</span></span>
<span class="line"><span>    time1 = Time(seconds=10)</span></span>
<span class="line"><span>    time2 = Time(seconds=4)</span></span>
<span class="line"><span>    #Duration类使用方法，创建‘持续时间、一段时间’</span></span>
<span class="line"><span>    duration1 = Duration(seconds=3)</span></span>
<span class="line"><span>    duration2 = Duration(seconds=5)</span></span>
<span class="line"><span>          </span></span>
<span class="line"><span>    # 时刻可以进行比较</span></span>
<span class="line"><span>    node.get_logger().info(&quot;time1 &gt;= time2 ? %d&quot; % (time1 &gt;= time2))</span></span>
<span class="line"><span>    node.get_logger().info(&quot;time1 &lt; time2 ? %d&quot; % (time1 &lt; time2))</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    # 时间段与时刻可以数学运算</span></span>
<span class="line"><span>    t3 = time1 + duration1</span></span>
<span class="line"><span>    t4 = time1 - time2    </span></span>
<span class="line"><span>    t5 = time1 - duration1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    node.get_logger().info(&quot;t3 = %d&quot; % t3.nanoseconds)</span></span>
<span class="line"><span>    node.get_logger().info(&quot;t4 = %d&quot; % t4.nanoseconds)</span></span>
<span class="line"><span>    node.get_logger().info(&quot;t5 = %d&quot; % t5.nanoseconds)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 时间段可以进行比较</span></span>
<span class="line"><span>    node.get_logger().info(&quot;-&quot; * 80)</span></span>
<span class="line"><span>    node.get_logger().info(&quot;duration1 &gt;= duration2 ? %d&quot; % (duration1 &gt;= duration2))</span></span>
<span class="line"><span>    node.get_logger().info(&quot;duration1 &lt; duration2 ? %d&quot; % (duration1 &lt; duration2))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    rclpy.shutdown()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    main()</span></span></code></pre></div><ul><li>配置对应的setup.py配置文件，在console_scripts中添加</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39;TimeDuration_demo=learning_time.TimeDuration_demo:main&#39;</span></span></code></pre></div><img src="`+d+`" alt="image-20250905160751388" style="zoom:50%;"><ul><li>编译功能包</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>colcon build --packages-select learning_time</span></span></code></pre></div><ul><li>刷新工作空间环境并运行节点</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> source ./install/setup.bash</span></span>
<span class="line"><span>ros2 run learning_time TimeDuration_demo</span></span></code></pre></div><img src="`+u+'" alt="image-20250905160840013" style="zoom:67%;"><h1 id="ros2常用命令工具" tabindex="-1">ROS2常用命令工具 <a class="header-anchor" href="#ros2常用命令工具" aria-label="Permalink to &quot;ROS2常用命令工具&quot;">​</a></h1><h2 id="ros2-pkg" tabindex="-1">ros2 pkg <a class="header-anchor" href="#ros2-pkg" aria-label="Permalink to &quot;ros2 pkg&quot;">​</a></h2><h3 id="快速创建功能包ros2-pkg-create" tabindex="-1">快速创建功能包ros2 pkg create <a class="header-anchor" href="#快速创建功能包ros2-pkg-create" aria-label="Permalink to &quot;快速创建功能包ros2 pkg create&quot;">​</a></h3><p>功能：创建功能包，创建时候需要指定包名、编译方式、依赖项等。</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 pkg create &lt;package_name&gt; --build-type &lt;build-type&gt; --dependencies &lt;dependencies&gt;</span></span></code></pre></div><p>ros2命令中：</p><ul><li><strong>pkg</strong>：表示功能包相关的功能；</li><li><strong>create</strong>：表示创建功能包；</li><li><strong>package_name</strong>：必须项：新建功能包的名字；</li><li><strong>build-type</strong>：必须项：表示新创建的功能包是C++还是Python的，如果使用C++或者C，那这里就跟ament_cmake，如果使用Python，就跟ament_python；</li><li><strong>dependencies</strong>：可选项:表示功能包的依赖项，C++功能包需包含rclcpp，Python功能包需包含rclpy ,还有其它需要的依赖</li></ul><h3 id="查看所有功能包ros2-pkg-list" tabindex="-1">查看所有功能包ros2 pkg list <a class="header-anchor" href="#查看所有功能包ros2-pkg-list" aria-label="Permalink to &quot;查看所有功能包ros2 pkg list&quot;">​</a></h3><p>功能：查看系统中功能包列表</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 pkg list</span></span></code></pre></div><img src="'+h+'" alt="image-20230427154146879" style="zoom:50%;"><h3 id="查看所有可执行文件ros2-pkg-executeables" tabindex="-1">查看所有可执行文件ros2 pkg executeables <a class="header-anchor" href="#查看所有可执行文件ros2-pkg-executeables" aria-label="Permalink to &quot;查看所有可执行文件ros2 pkg executeables&quot;">​</a></h3><p>功能：查看某个包内所有可执行文件</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 pkg executables pkg_name</span></span></code></pre></div><img src="'+g+'" alt="image-20230427154419005" style="zoom:50%;"><h2 id="节点运行-ros2-run" tabindex="-1">节点运行 ros2 run <a class="header-anchor" href="#节点运行-ros2-run" aria-label="Permalink to &quot;节点运行 ros2 run&quot;">​</a></h2><p>功能：运行功能包节点程序</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 run pkg_name node_name</span></span></code></pre></div><ul><li>pkg_name：功能包名字</li><li>node_name：可执行程序的名字</li></ul><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427155359745.png" alt="image-20230427155359745" style="zoom:50%;"><h2 id="节点相关工具-ros2-node" tabindex="-1">节点相关工具 ros2 node <a class="header-anchor" href="#节点相关工具-ros2-node" aria-label="Permalink to &quot;节点相关工具 ros2 node&quot;">​</a></h2><h3 id="查看所有节点ros2-node-list" tabindex="-1">查看所有节点ros2 node list <a class="header-anchor" href="#查看所有节点ros2-node-list" aria-label="Permalink to &quot;查看所有节点ros2 node list&quot;">​</a></h3><p>功能： 罗列出所有在当前域内节点名称</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ros2 node list</span></span></code></pre></div><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427155655753.png" alt="image-20230427155655753" style="zoom:50%;"><h3 id="查看节点信息ros2-node-info" tabindex="-1">查看节点信息ros2 node info <a class="header-anchor" href="#查看节点信息ros2-node-info" aria-label="Permalink to &quot;查看节点信息ros2 node info&quot;">​</a></h3><p>功能： 查看节点详细信息，包括订阅、发布的消息，开启的服务和动作等</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 node info node_name</span></span></code></pre></div><ul><li>node_name：需要查看的节点名称</li></ul><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427160001101.png" alt="image-20230427160001101" style="zoom:50%;"><h2 id="话题相关工具-ros2-topic" tabindex="-1">话题相关工具 ros2 topic <a class="header-anchor" href="#话题相关工具-ros2-topic" aria-label="Permalink to &quot;话题相关工具 ros2 topic&quot;">​</a></h2><h3 id="查看运行中的话题ros2-topic-list" tabindex="-1">查看运行中的话题ros2 topic list <a class="header-anchor" href="#查看运行中的话题ros2-topic-list" aria-label="Permalink to &quot;查看运行中的话题ros2 topic list&quot;">​</a></h3><p>功能：罗列出当前域内的所有话题</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 topic list</span></span></code></pre></div><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427160351051.png" alt="image-20230427160351051" style="zoom:50%;"><h3 id="查看话题信息ros2-topic-info" tabindex="-1">查看话题信息ros2 topic info <a class="header-anchor" href="#查看话题信息ros2-topic-info" aria-label="Permalink to &quot;查看话题信息ros2 topic info&quot;">​</a></h3><p>功能：显示话题消息类型，订阅者/发布者数量</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 topic info topic_name</span></span></code></pre></div><ul><li>topic_name：需要查询的话题的名字</li></ul><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427160625594.png" alt="image-20230427160625594" style="zoom:50%;"><h3 id="查看话题类型ros2-topic-type" tabindex="-1">查看话题类型ros2 topic type <a class="header-anchor" href="#查看话题类型ros2-topic-type" aria-label="Permalink to &quot;查看话题类型ros2 topic type&quot;">​</a></h3><p>功能：查看话题的消息类型</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 topic type topic_name</span></span></code></pre></div><ul><li>topic_name：需要查询话题类型的名字</li></ul><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427161056536.png" alt="image-20230427161056536" style="zoom:50%;"><h3 id="查看话题频率ros2-topic-hz" tabindex="-1">查看话题频率ros2 topic hz <a class="header-anchor" href="#查看话题频率ros2-topic-hz" aria-label="Permalink to &quot;查看话题频率ros2 topic hz&quot;">​</a></h3><p>功能：显示话题平均发布频率</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 topic hz topic_name</span></span></code></pre></div><ul><li>topic_name：需要查询话题频率的名字</li></ul><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427161721650.png" alt="image-20230427161721650" style="zoom:50%;"><h3 id="查看话题内容ros2-topic-echo" tabindex="-1">查看话题内容ros2 topic echo <a class="header-anchor" href="#查看话题内容ros2-topic-echo" aria-label="Permalink to &quot;查看话题内容ros2 topic echo&quot;">​</a></h3><p>功能：在终端打印话题消息，类似于一个订阅者</p><p>格式：ros2 topic echo topic_name</p><ul><li>topic_name：需要打印消息的话题的名字</li></ul><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427162312888.png" alt="image-20230427162312888" style="zoom:50%;"><h3 id="手动发布一个话题ros2-topic-pub" tabindex="-1">手动发布一个话题ros2 topic pub <a class="header-anchor" href="#手动发布一个话题ros2-topic-pub" aria-label="Permalink to &quot;手动发布一个话题ros2 topic pub&quot;">​</a></h3><p>功能：在终端发布指定话题消息</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 topic pub topic_name message_type message_content</span></span></code></pre></div><ul><li>topic_name：需要发布话题消息的话题的名字</li><li>message_type：话题的数据类型</li><li>message_content：消息内容</li></ul><p>默认是以1Hz的频率循环发布，可以设置以下参数，</p><ul><li>参数-1只发布一次，ros2 topic pub -1 topic_name message_type message_content</li><li>参数-t count循环发布count次结束，ros2 topic pub -t count topic_name message_type message_content</li><li>参数-r count以count Hz的频率循环发布，ros2 topic pub -r count topic_name message_type message_content</li></ul><p>示例：</p><ul><li>通过命令行发布速度指令</li><li>这里需要注意的是每个冒号后是有个空格，否则的话会提示格式错误</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 topic pub turtle1/cmd_vel geometry_msgs/msg/Twist &quot;{linear: {x: 0.5, y: 0.0, z: 0.0}, angular: {x: 0.0, y: 0.0, z: 0.2}}&quot;</span></span></code></pre></div><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20250905163149992.png" alt="image-20250905163149992" style="zoom:50%;"><h2 id="接口相关工具ros2-interface" tabindex="-1">接口相关工具ros2 interface <a class="header-anchor" href="#接口相关工具ros2-interface" aria-label="Permalink to &quot;接口相关工具ros2 interface&quot;">​</a></h2><h3 id="查看所有接口ros2-interface-list" tabindex="-1">查看所有接口ros2 interface list <a class="header-anchor" href="#查看所有接口ros2-interface-list" aria-label="Permalink to &quot;查看所有接口ros2 interface list&quot;">​</a></h3><p>功能：罗列当前系统的所有接口，包括话题、服务、动作。</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 interface list</span></span></code></pre></div><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427164755075.png" alt="image-20230427164755075" style="zoom:50%;"><h3 id="查看接口信息ros2-interface-show" tabindex="-1">查看接口信息ros2 interface show <a class="header-anchor" href="#查看接口信息ros2-interface-show" aria-label="Permalink to &quot;查看接口信息ros2 interface show&quot;">​</a></h3><p>功能：显示指定接口的详细内容</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 interface show interface_name</span></span></code></pre></div><ul><li>interface_name：需要显示的接口内容的名字</li></ul><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427165057647.png" alt="image-20230427165057647" style="zoom:50%;"><h2 id="服务相关工具-ros2-service" tabindex="-1">服务相关工具 ros2 service <a class="header-anchor" href="#服务相关工具-ros2-service" aria-label="Permalink to &quot;服务相关工具 ros2 service&quot;">​</a></h2><h3 id="查看所有服务ros2-service-list" tabindex="-1">查看所有服务ros2 service list <a class="header-anchor" href="#查看所有服务ros2-service-list" aria-label="Permalink to &quot;查看所有服务ros2 service list&quot;">​</a></h3><p>功能：罗列出当前域内所有的服务</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 interface show interface_name</span></span></code></pre></div><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427172236875.png" alt="image-20230427172236875" style="zoom:50%;"><h3 id="手动调用服务ros2-service-call" tabindex="-1">手动调用服务ros2 service call <a class="header-anchor" href="#手动调用服务ros2-service-call" aria-label="Permalink to &quot;手动调用服务ros2 service call&quot;">​</a></h3><p>功能：调用指定服务</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 interface call service_name service_Type arguments</span></span></code></pre></div><ul><li>service_name：需要调用的服务</li><li>service_Type：服务数据类型</li><li>arguments：提供服务需要的参数</li></ul><p>例如，调用生成海龟服务</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /spawn turtlesim/srv/Spawn &quot;{x: 2, y: 2, theta: 0.2, name: &#39;turtle10&#39;}&quot;</span></span></code></pre></div><img src="https://www.yahboom.com/public/upload/upload-html/1757401713/image-20230427173625631.png" alt="image-20230427173625631" style="zoom:50%;"><h1 id="ros2-rviz2使用" tabindex="-1">ROS2 Rviz2使用 <a class="header-anchor" href="#ros2-rviz2使用" aria-label="Permalink to &quot;ROS2 Rviz2使用&quot;">​</a></h1><h2 id="rviz2简介" tabindex="-1">Rviz2简介 <a class="header-anchor" href="#rviz2简介" aria-label="Permalink to &quot;Rviz2简介&quot;">​</a></h2><p>机器人开发过程中，各种各样的功能，如果我们只是从数据层面去做分析，很难快速理解数据的效果，比如机器人模型，我们需要知道自己设计的模型长啥样，还有模型内部众多坐标系在运动过程中都在哪些位置。</p><p>再比如机械臂运动规划和移动机器人自主导航，我们希望可以看到机器人周边的环境、规划的路径，当然还有传感器的信息，摄像头、三维相机、激光雷达等等，数据是用来做计算的，可视化的效果才是给人看的。</p><p>所以，数据可视化可以大大提高开发效率，Rviz2就是这样一款机器人开发过程中的数据可视化软件，机器人模型、传感器信息、环境信息等等，全都可以在这里搞定。</p><ul><li>如果有实体机器人可以在机器人主控端启动rviz练习本节课程内容，如果没有实体机器人，我们可以通过gazebo仿真的方式启动turtlebot3仿真机器人，来模拟激光雷达、相机等话题，方便接下来的数据可视化</li></ul><p>**注意：**以下的安装步骤非必须，如果手中有实体机器人，设置好多机通信之后可以直接使用实机的雷达信息，可以自行选择使用实机雷达或虚拟仿真机器人；以下内容适合没有实机的用户使用。</p><ul><li>本节课程以仿真机器人为例，教学rviz2的可视化功能，不管是实机还是仿真机器人，rviz2的操作流程都是相同的。</li><li>安装tutlebot3模拟器功能包</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install ros-${ROS_DISTRO}-turtlebot3*</span></span></code></pre></div><ul><li>安装ros和gazebo桥接工具</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install ros-${ROS_DISTRO}-ros-gz</span></span></code></pre></div><ul><li>设置turtlebot3机器人类型环境变量</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export TURTLEBOT3_MODEL=waffle</span></span></code></pre></div><ul><li>启动gazebo仿真环境</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch turtlebot3_gazebo turtlebot3_world.launch.py</span></span></code></pre></div><p><img src="https://www.yahboom.com/public/upload/upload-html/1757496837/image-20250905164250419.png" alt="image-20250905164250419" loading="lazy"></p><h2 id="rviz2使用教程" tabindex="-1">Rviz2使用教程 <a class="header-anchor" href="#rviz2使用教程" aria-label="Permalink to &quot;Rviz2使用教程&quot;">​</a></h2><p>启动一个终端，使用如下命令即可启动：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rviz2</span></span></code></pre></div><p>如果是在docker中启动，请务必确保已经开启了GUI显示。</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496837/image-20231031104047357.png" alt="image-20231031104047357" style="zoom:33%;"><h3 id="图像数据可视化" tabindex="-1">图像数据可视化 <a class="header-anchor" href="#图像数据可视化" aria-label="Permalink to &quot;图像数据可视化&quot;">​</a></h3><p>在左侧Displays窗口中点击“Add”，找到Image显示项，OK确认后就可以加入显示列表啦，然后配置好该显示项订阅的图像话题，就可以顺利看到机器人的摄像头图像啦。</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496837/image-20231031104244974.png" alt="image-20231031104244974" style="zoom:50%;"><ul><li>将<code>Fixed Frame</code>选择为<code>base_footprint</code>坐标系，放置坐标变换错误</li><li>选择相机彩色画面话题<code>/camera/image_raw</code></li><li>此时我们可以看到Camera窗口中看到当前仿真机器人的视角画面</li></ul><img src="https://www.yahboom.com/public/upload/upload-html/1757496837/image-20250905165626951.png" alt="image-20250905165626951" style="zoom:50%;"><h3 id="雷达数据可视化" tabindex="-1">雷达数据可视化 <a class="header-anchor" href="#雷达数据可视化" aria-label="Permalink to &quot;雷达数据可视化&quot;">​</a></h3><p>在左侧Displays窗口中点击“Add”，选择Laserscan，然后配置订阅的话题名，此时就可以看到激光点啦</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496837/image-20231031104528033.png" alt="image-20231031104528033" style="zoom:50%;"><ul><li><code>LaserScan</code>的<code>Topic</code>话题选择<code>/sacn</code></li><li>此时我们就可以看到激光雷达的点云轮廓</li></ul><img src="https://www.yahboom.com/public/upload/upload-html/1757496837/image-20250905170346004.png" alt="image-20250905170346004" style="zoom:50%;"><h3 id="机器人模型可视化" tabindex="-1">机器人模型可视化 <a class="header-anchor" href="#机器人模型可视化" aria-label="Permalink to &quot;机器人模型可视化&quot;">​</a></h3><p>在左侧Displays窗口中点击“Add”，选择RobotModel</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496837/image-20250905170711426.png" alt="image-20250905170711426" style="zoom:50%;"><ul><li>在机器人的<code>DescriptionTopic</code>选项中，选择话题<code>/robot_deseription</code></li><li>此时我们就可以在Rviz2中看到机器人的可视化模型</li></ul><img src="https://www.yahboom.com/public/upload/upload-html/1757496837/image-20250905170923074.png" alt="image-20250905170923074" style="zoom:67%;"><h1 id="ros2-rqt工具箱" tabindex="-1">ROS2 Rqt工具箱 <a class="header-anchor" href="#ros2-rqt工具箱" aria-label="Permalink to &quot;ROS2 Rqt工具箱&quot;">​</a></h1><h2 id="rqt简介" tabindex="-1">Rqt简介 <a class="header-anchor" href="#rqt简介" aria-label="Permalink to &quot;Rqt简介&quot;">​</a></h2><p>Rqt是ROS提供的另外一种模块化可视化工具，正如Rqt的命名，它和Rviz一样，也是基于QT可视化工具开发而来，在使用前，我们需要通过这样一句指令进行安装，然后就可以通过rqt这个命令启动使用了。</p><h2 id="rqt使用教程" tabindex="-1">Rqt使用教程 <a class="header-anchor" href="#rqt使用教程" aria-label="Permalink to &quot;Rqt使用教程&quot;">​</a></h2><p>常用的<code>rqt</code>启动命令有：</p><ul><li><p>方式1：<code>rqt</code></p></li><li><p>方式2：<code>ros2 run rqt_gui rqt_gui</code></p></li></ul><h3 id="插件使用" tabindex="-1">插件使用 <a class="header-anchor" href="#插件使用" aria-label="Permalink to &quot;插件使用&quot;">​</a></h3><p>启动rqt之后，可以通过plugins添加所需的插件：</p><img src="'+m+'" alt="img" style="zoom:50%;"><p>在plugins中包含了话题、服务、动作、参数、日志等等相关的插件，我们可以按需选用，方便的实现ROS2程序调试。使用示例如下。</p><h4 id="topic-插件" tabindex="-1">topic 插件 <a class="header-anchor" href="#topic-插件" aria-label="Permalink to &quot;topic 插件&quot;">​</a></h4><p>添加topic插件并发送速度指令控制乌龟运动。</p><img src="'+b+'" alt="img" style="zoom:50%;"><h3 id="service插件" tabindex="-1">service插件 <a class="header-anchor" href="#service插件" aria-label="Permalink to &quot;service插件&quot;">​</a></h3><p>添加 service 插件并发送请求，在制定位置生成一只乌龟。</p><img src="'+_+'" alt="img" style="zoom:50%;"><h3 id="参数插件" tabindex="-1">参数插件 <a class="header-anchor" href="#参数插件" aria-label="Permalink to &quot;参数插件&quot;">​</a></h3><p>通过参数插件动态修改乌龟窗体背景颜色。</p><img src="'+v+`" alt="img" style="zoom:50%;"><h1 id="ros2录制回放工具" tabindex="-1">ROS2录制回放工具 <a class="header-anchor" href="#ros2录制回放工具" aria-label="Permalink to &quot;ROS2录制回放工具&quot;">​</a></h1><h2 id="录制回放工具简介" tabindex="-1">录制回放工具简介 <a class="header-anchor" href="#录制回放工具简介" aria-label="Permalink to &quot;录制回放工具简介&quot;">​</a></h2><p>ROS2中常用的录制回放工具——bag2，这个工具用于记录话题的数据。我们就可以使用这个指令将话题数据存储为文件 ，后续我们无需启动节点，直接可以将bag文件里的话题数据发布出来。</p><p>这个工具在我们做一个真实机器人的时候非常有用，比如我们可以录制一段机器人发生问题的话题数据，录制完成后可以多次发布出来进行测试和实验，也可以将话题数据分享给别人用于验证算法等。</p><p>我们尝试使用bag工具来记录话题数据，并二次重放。</p><h2 id="使用教程" tabindex="-1">使用教程 <a class="header-anchor" href="#使用教程" aria-label="Permalink to &quot;使用教程&quot;">​</a></h2><ul><li>启动要录制的话题节点</li></ul><p>如ros2 demo中的talker：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 run demo_nodes_py talker</span></span></code></pre></div><ul><li>记录</li></ul><p><code>/topic-name</code> 为话题名字</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 记录单个话题</span></span>
<span class="line"><span>ros2 bag record /topic-name</span></span>
<span class="line"><span># 记录多个话题</span></span>
<span class="line"><span>ros2 bag record topic-name1 topic-name2</span></span>
<span class="line"><span># 记录所有话题</span></span>
<span class="line"><span>ros2 bag record -a</span></span></code></pre></div><p>其它选项</p><p>-o name 自定义输出文件的名字</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 bag record -o file-name topic-name</span></span></code></pre></div><p>-s 存储格式</p><p>目前仅支持sqllite3,其他还带拓展</p><ul><li>查看录制出话题的信息</li></ul><p>我们在播放一个视频前，可以通过文件信息查看视频的相关信息，比如话题记录的时间，大小，类型，数量</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 假设录制的file为rosbag2_2023_10_31-07_58_23</span></span>
<span class="line"><span>ros2 bag info rosbag2_2023_10_31-07_58_23</span></span></code></pre></div><ul><li>播放</li></ul><p>接着我们就可以重新播放数据，使用下面的指令可以播放数据</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 bag play rosbag2_2023_10_31-07_58_23</span></span></code></pre></div><ul><li>查看</li></ul><p>使用ros2的topic的指令来查看数据</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 topic echo /chatter</span></span></code></pre></div><p>播放选项</p><p>1、倍速播放 -r</p><p>-r选项可以修改播放速率，比如 -r 值，比如 -r 10,就是10倍速，十倍速播放话题</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 bag play rosbag2_2023_10_31-07_58_23 -r 10</span></span></code></pre></div><p>2、循环播放 -l</p><p>单曲循环就是它了</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 bag play rosbag2_2023_10_31-07_58_23 -l</span></span></code></pre></div><p>3、播放单个话题</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 bag play rosbag2_2023_10_31-07_58_23 --topics /chatter</span></span></code></pre></div><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><ul><li>运行talker节点</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 run demo_nodes_py talker</span></span></code></pre></div><ul><li>录制</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 记录所有话题</span></span>
<span class="line"><span>ros2 bag record -a</span></span></code></pre></div><p><img src="https://www.yahboom.com/public/upload/upload-html/1757401807/image-20231031162153843.png" alt="image-20231031162153843" loading="lazy"></p><p>如何停止录制呢？我们直接在终端中使用<code>Ctrl+C</code>指令打断录制即可</p><p>接着你会在终端中发现多处一个文件夹，名字叫做<code>rosbag2_2023_10_31-08_21_21</code></p><p>打开文件夹，可以看到内容</p><p><img src="https://www.yahboom.com/public/upload/upload-html/1757401807/image-20231031162443246.png" alt="image-20231031162443246" loading="lazy"></p><p>这样我们就完成了录制。</p><ul><li>播放并查看，这里我们循环播放</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 bag play rosbag2_2023_10_31-07_58_23 -l</span></span></code></pre></div><p>开启另一个终端查看topic：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 topic echo /chatter</span></span></code></pre></div><img src="https://www.yahboom.com/public/upload/upload-html/1757401807/image-20231031162719003.png" alt="image-20231031162719003" style="zoom:50%;"><h1 id="ros2-urdf模型" tabindex="-1">ROS2 URDF模型 <a class="header-anchor" href="#ros2-urdf模型" aria-label="Permalink to &quot;ROS2 URDF模型&quot;">​</a></h1><h2 id="urdf简介" tabindex="-1">URDF简介 <a class="header-anchor" href="#urdf简介" aria-label="Permalink to &quot;URDF简介&quot;">​</a></h2><p>ROS中的建模方法叫做URDF，全称是统一机器人描述格式，不仅可以清晰描述机器人自身的模型，还可以描述机器人的外部环境。URDF模型文件使用的是XML格式。</p><p>solidworks模型转URDF插件：<a href="https://wiki.ros.org/sw_urdf_exporter" target="_blank" rel="noreferrer">sw_urdf_exporter - ROS Wiki</a></p><ul><li>机器人的组成</li></ul><p>建模描述机器人的过程中，我们自己需要先熟悉机器人的组成和参数，比如机器人一般是由<strong>硬件结构、驱动系统、传感器系统、控制系统</strong>四大部分组成，市面上一些常见的机器人，无论是移动机器人还是机械臂，我们都可以按照这四大组成部分进行分解。</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20220528144350325.png" alt="image-20220528144350325" style="zoom:67%;"><ul><li>硬件结构就是底盘、外壳、电机等实打实可以看到的设备；</li><li>驱动系统就是可以驱使这些设备正常使用的装置，比如电机的驱动器，电源管理系统等；</li><li>传感系统包括电机上的编码器、板载的IMU、安装的摄像头、雷达等等，便于机器人感知自己的状态和外部的环境；</li><li>控制系统就是我们开发过程的主要载体了，一般是树莓派、电脑等计算平台，以及里边的操作系统和应用软件。</li></ul><p>机器人建模的过程，其实就是按照类似的思路，通过建模语言，把机器人每一个部分都描述清楚，再组合起来的过程。</p><h2 id="urdf语法" tabindex="-1">URDF语法 <a class="header-anchor" href="#urdf语法" aria-label="Permalink to &quot;URDF语法&quot;">​</a></h2><h3 id="连杆link的描述" tabindex="-1">连杆Link的描述 <a class="header-anchor" href="#连杆link的描述" aria-label="Permalink to &quot;连杆Link的描述&quot;">​</a></h3><p>标签用来描述机器人某个刚体部分的外观和物理属性，外观包括尺寸、颜色、形状，物理属性包括质量、惯性矩阵、碰撞参数等。</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20220528144534685.png" alt="image-20220528144534685" style="zoom:50%;"><p>以这个机械臂连杆为例，它的link描述如下：</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20220528144549092.png" alt="image-20220528144549092" style="zoom:67%;"><p>link标签中的name表示该连杆的名称，我们可以自定义，未来joint连接link的时候，会使用到这个名称。</p><p>link里边的部分用来描述机器人的外观，比如：</p><ul><li>表示几何形状，里边使用调用了一个在三维软件中提前设计好的蓝色外观，就是这个stl文件，看上去和真实机器人是一致的</li><li>表示坐标系相对初始位置的偏移，分别是x、y、z方向上的平移，和roll、pitch、raw旋转，不需要偏移的话，就全为0。</li></ul><p>第二个部分，描述碰撞参数，里边的内容似乎和一样，也有和，看似相同，其实区别还是比较大的。</p><ul><li>部分重在描述机器人看上去的状态，也就是视觉效果；</li><li>部分则是描述机器人运动过程中的状态，比如机器人与外界如何接触算作碰撞。</li></ul><p>在这个机器人模型中，蓝色部分是通过来描述的，在实际控制过程中，这样复杂的外观在计算碰撞检测时，要求的算力较高，为了简化计算，我们将碰撞检测用的模型简化为了绿色框的圆柱体，也就是里边描述的形状。坐标系偏移也是类似，可以描述刚体质心的偏移。</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20220528144603646.png" alt="image-20220528144603646" style="zoom:50%;"><p>如果是移动机器人的话，link也可以用来描述小车的车体、轮子等部分。</p><h3 id="关节joint描述" tabindex="-1">关节Joint描述 <a class="header-anchor" href="#关节joint描述" aria-label="Permalink to &quot;关节Joint描述&quot;">​</a></h3><p>机器人模型中的刚体最终要通过关节joint连接之后，才能产生相对运动。</p><p>URDF中的关节有六种运动类型。</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20220528144655899.png" alt="image-20220528144655899" style="zoom:50%;"><ol><li>continuous，描述旋转运动，可以围绕某一个轴无限旋转，比如小车的轮子，就属于这种类型。</li><li>revolute，也是旋转关节，和continuous类型的区别在于不能无限旋转，而是带有角度限制，比如机械臂的两个连杆，就属于这种运动。</li><li>prismatic，是滑动关节，可以沿某一个轴平移，也带有位置的极限，一般直线电机就是这种运动方式。</li><li>fixed，固定关节，是唯一一种不允许运动的关节，不过使用还是比较频繁的，比如相机这个连杆，安装在机器人上，相对位置是不会变化的，此时使用的连接方式就是Fixed。</li><li>Floating是浮动关节，第六种planar是平面关节，这两种使用相对较少。</li></ol><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20220528144722751.png" alt="image-20220528144722751" style="zoom:50%;"><p>在URDF模型中，每一个link都使用这样一段xml内容描述，比如关节的名字叫什么，运动类型是哪一种。</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20220528144729633-16537204524521.png" alt="image-20220528144729633" style="zoom:50%;"><ul><li>parent标签：描述父连杆；</li><li>child标签：描述子连杆，子连杆会相对父连杆发生运动；</li><li>origin：表示两个连杆坐标系之间的关系，也就是图中红色的向量，可以理解为这两个连杆该如何安装到一起；</li><li>axis表示关节运动轴的单位向量，比如z等于1，就表示这个旋转运动是围绕z轴的正方向进行的；</li><li>limit就表示运动的一些限制了，比如最小位置，最大位置，和最大速度等。</li></ul><h3 id="完整机器人模型" tabindex="-1">完整机器人模型 <a class="header-anchor" href="#完整机器人模型" aria-label="Permalink to &quot;完整机器人模型&quot;">​</a></h3><p><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20220528144900705.png" alt="image-20220528144900705" loading="lazy"></p><p>最终所有的link和joint标签完成了对机器人每个部分的描述和组合，全都放在一个robot标签中，就形成了完整的机器人模型。</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20220528144824234.png" alt="image-20220528144824234" style="zoom:50%;"><p>所以大家在看某一个URDF模型时，先不着急看每一块代码的细节，先来找link和joint，看下这个机器人是由哪些部分组成的，了解完全局之后，再看细节。</p><h3 id="创建机器人模型" tabindex="-1">创建机器人模型 <a class="header-anchor" href="#创建机器人模型" aria-label="Permalink to &quot;创建机器人模型&quot;">​</a></h3><p>以muto的模型为例，将本节教程文件夹中的<code>yahboomcar_description</code>功能包复制到工作空间的src目录下：</p><p><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20250905184735806.png" alt="image-20250905184735806" loading="lazy"></p><ul><li>urdf：存放机器人模型的URDF或xacro文件</li><li>meshes：放置URDF中引用的模型渲染文件</li><li>launch：保存相关启动文件</li><li>rviz：保存rviz的配置文件</li></ul><p>之后编译功能包</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>colcon build --packages-select yahboomcar_description</span></span></code></pre></div><h3 id="模型可视化效果" tabindex="-1">模型可视化效果 <a class="header-anchor" href="#模型可视化效果" aria-label="Permalink to &quot;模型可视化效果&quot;">​</a></h3><ul><li>刷新环境变量，然后运行启动命令</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch yahboomcar_description display.launch.py</span></span></code></pre></div><p>之后会自动启动rviz，并显示机器人模型：</p><img src="https://www.yahboom.com/public/upload/upload-html/1757496907/image-20250905185113862.png" alt="image-20250905185113862" style="zoom:50%;"><h1 id="ros2-gazebo仿真平台" tabindex="-1">ROS2 Gazebo仿真平台 <a class="header-anchor" href="#ros2-gazebo仿真平台" aria-label="Permalink to &quot;ROS2 Gazebo仿真平台&quot;">​</a></h1><h2 id="gazebo简介" tabindex="-1">Gazebo简介 <a class="header-anchor" href="#gazebo简介" aria-label="Permalink to &quot;Gazebo简介&quot;">​</a></h2><p>Gazebo是ROS系统中最为常用的<strong>三维物理仿真平台</strong>，支持动力学引擎，可以实现高质量的图形渲染，不仅可以模拟机器人及周边环境，还可以加入摩擦力、弹性系数等物理属性。</p><p>比如我们要开发一个火星车，那就可以在Gazebo中模拟火星表面的环境，再比如我们做无人机，续航和限飞都导致我们没有办法频繁用实物做实验，此时不妨使用Gazebo先做仿真，等算法开发的差不多了，再部署到实物上来运行。</p><p>所以类似Gazebo这样的仿真平台，可以帮助我们验证机器人算法、优化机器人设计、测试机器人场景应用，为机器人开发提供更多可能。</p><p><strong>注意：本章节只做了解学习，教程中并未配置该环境，因为这边直接用的真机调试</strong></p><h2 id="安装运行" tabindex="-1">安装运行 <a class="header-anchor" href="#安装运行" aria-label="Permalink to &quot;安装运行&quot;">​</a></h2><ul><li>通过命令apt进行安装gazebo</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install ros-\${ROS_DISTRO}-gazebo-*</span></span></code></pre></div><ul><li>运行gazebo</li><li>通过以下命令启动或直接通过桌面图标启动</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gazebo --verbose -s libgazebo_ros_init.so -s libgazebo_ros_factory.so</span></span></code></pre></div><p>运行之后可以看到如下页面：</p><img src="https://www.yahboom.com/public/upload/upload-html/1757401978/ff2db85fe6294c63a4f666d7396e8a28.png" alt="img" style="zoom:50%;"><ul><li>可选项：为保证模型顺利加载，可以将请将离线模型下载并放置到~/.gazebo/models路径下，下载链接如下：<a href="https://github.com/osrf/gazebo_models" target="_blank" rel="noreferrer">https://github.com/osrf/gazebo_models</a></li></ul><h3 id="gazebo启动节点与服务" tabindex="-1">gazebo启动节点与服务 <a class="header-anchor" href="#gazebo启动节点与服务" aria-label="Permalink to &quot;gazebo启动节点与服务&quot;">​</a></h3><p>1、查看节点</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 node list</span></span></code></pre></div><img src="https://www.yahboom.com/public/upload/upload-html/1757401978/image-20250905185639464.png" alt="image-20250905185639464" style="zoom:67%;"><p>正确返回：/gazebo 2、查看节点的对外提供的服务：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service list</span></span></code></pre></div><p>可以看出如下的结果：</p><img src="https://www.yahboom.com/public/upload/upload-html/1757401978/image-20250905185658045.png" alt="image-20250905185658045" style="zoom:67%;"><p>出去最后几个常规的服务，我们只注意前三个特殊的服务：</p><ul><li>/spawn_entity，用于加载模型到gazebo中</li><li>/get_model_list，用于获取模型列表</li><li>/delete_entity，用于删除gazbeo中已经加载的模型</li></ul><h3 id="创建功能包" tabindex="-1">创建功能包 <a class="header-anchor" href="#创建功能包" aria-label="Permalink to &quot;创建功能包&quot;">​</a></h3><ul><li>创建一个myrobot功能包，用来存放我们的URDF模型文件和启动文件</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 pkg create myrobot --build-type ament_cmake</span></span></code></pre></div><ul><li>进入到myrobot的目录下，创建launch、urdf文件夹，在urdf文件夹下创建一个demo01_base.urdf文件，这个文件就是一个简单的演示文件，只有一个基础的立方体。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;robot name=&quot;myrobot&quot;&gt;</span></span>
<span class="line"><span>    &lt;link name=&quot;base_link&quot;&gt;</span></span>
<span class="line"><span>        &lt;visual&gt;</span></span>
<span class="line"><span>            &lt;geometry&gt;</span></span>
<span class="line"><span>                &lt;box size=&quot;0.2 0.2 0.2&quot;/&gt;</span></span>
<span class="line"><span>            &lt;/geometry&gt;</span></span>
<span class="line"><span>            &lt;origin xyz=&quot;0.0 0.0 0.0&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/visual&gt;</span></span>
<span class="line"><span>        &lt;collision&gt;</span></span>
<span class="line"><span>            &lt;geometry&gt;</span></span>
<span class="line"><span>                &lt;box size=&quot;0.2 0.2 0.2&quot;/&gt;</span></span>
<span class="line"><span>            &lt;/geometry&gt;</span></span>
<span class="line"><span>            &lt;origin xyz=&quot;0.0 0.0 0.0&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/collision&gt;</span></span>
<span class="line"><span>        &lt;inertial&gt;</span></span>
<span class="line"><span>            &lt;mass value=&quot;0.1&quot;/&gt;</span></span>
<span class="line"><span>            &lt;inertia ixx=&quot;0.000190416666667&quot; ixy=&quot;0&quot; ixz=&quot;0&quot; iyy=&quot;0.0001904&quot; iyz=&quot;0&quot; izz=&quot;0.00036&quot;/&gt;</span></span>
<span class="line"><span>        &lt;/inertial&gt;</span></span>
<span class="line"><span>    &lt;/link&gt;</span></span>
<span class="line"><span>    &lt;gazebo reference=&quot;base_link&quot;&gt;</span></span>
<span class="line"><span>        &lt;material&gt;Gazebo/Red&lt;/material&gt;</span></span>
<span class="line"><span>    &lt;/gazebo&gt;</span></span>
<span class="line"><span>&lt;/robot&gt;</span></span></code></pre></div><h3 id="编写launch启动文件" tabindex="-1">编写launch启动文件 <a class="header-anchor" href="#编写launch启动文件" aria-label="Permalink to &quot;编写launch启动文件&quot;">​</a></h3><p>launch文件的编写，launch文件主要启动两个部分，启动Gazebo文件，然后将机器人模型加载到Gazebo中。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>start_gazebo_cmd =  ExecuteProcess(</span></span>
<span class="line"><span>        cmd=[&#39;gazebo&#39;, &#39;--verbose&#39;,&#39;-s&#39;, &#39;libgazebo_ros_init.so&#39;, &#39;-s&#39;, &#39;libgazebo_ros_factory.so&#39;],</span></span>
<span class="line"><span>        output=&#39;screen&#39;)</span></span></code></pre></div><p>这个命令就是启动Gazebo的，就是一个启动命令，并没有特别复杂的地方，下面是加载模型的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> spawn_entity_cmd = Node(</span></span>
<span class="line"><span>        package=&#39;gazebo_ros&#39;, </span></span>
<span class="line"><span>        executable=&#39;spawn_entity.py&#39;,</span></span>
<span class="line"><span>        arguments=[&#39;-entity&#39;, robot_name_in_model,  &#39;-file&#39;, urdf_model_path ], output=&#39;screen&#39;)</span></span></code></pre></div><p>这个命令注意后面两个参数-entity是模型文件中的名字，-file是通过urdf文件加载参数，后面我们还可以看到通过topic话题加载模型的。在launch目录下新建一个bringup_model.launch.py文件完整的启动文件如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import os</span></span>
<span class="line"><span>from launch import LaunchDescription</span></span>
<span class="line"><span>from launch.actions import ExecuteProcess</span></span>
<span class="line"><span>from launch_ros.actions import Node</span></span>
<span class="line"><span>from launch_ros.substitutions import FindPackageShare</span></span>
<span class="line"><span>from launch_ros.parameter_descriptions import ParameterValue</span></span>
<span class="line"><span>from launch.substitutions import Command</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def generate_launch_description():</span></span>
<span class="line"><span>    robot_name_in_model = &#39;myrobot&#39;</span></span>
<span class="line"><span>    package_name = &#39;myrobot&#39;</span></span>
<span class="line"><span>    urdf_name = &quot;demo01_base.urdf&quot;</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>    ld = LaunchDescription()</span></span>
<span class="line"><span>    pkg_share = FindPackageShare(package=package_name).find(package_name) </span></span>
<span class="line"><span>    urdf_model_path = os.path.join(pkg_share, f&#39;urdf/{urdf_name}&#39;)</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>    # Start Gazebo server</span></span>
<span class="line"><span>    start_gazebo_cmd =  ExecuteProcess(</span></span>
<span class="line"><span>        cmd=[&#39;gazebo&#39;, &#39;--verbose&#39;,&#39;-s&#39;, &#39;libgazebo_ros_init.so&#39;, &#39;-s&#39;, &#39;libgazebo_ros_factory.so&#39;],</span></span>
<span class="line"><span>        output=&#39;screen&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # Launch the robot</span></span>
<span class="line"><span>    spawn_entity_cmd = Node(</span></span>
<span class="line"><span>        package=&#39;gazebo_ros&#39;, </span></span>
<span class="line"><span>        executable=&#39;spawn_entity.py&#39;,</span></span>
<span class="line"><span>        arguments=[&#39;-entity&#39;, robot_name_in_model,  &#39;-file&#39;, urdf_model_path ], output=&#39;screen&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ld.add_action(start_gazebo_cmd)</span></span>
<span class="line"><span>    ld.add_action(spawn_entity_cmd)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    return ld</span></span></code></pre></div><ul><li>在Cmakelist中填入以下内容，用于将我们的urdf和launch文件夹安装进install目录下</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>install(</span></span>
<span class="line"><span>    DIRECTORY urdf launch</span></span>
<span class="line"><span>    DESTINATION share/\${PROJECT_NAME}</span></span>
<span class="line"><span>)</span></span></code></pre></div><ul><li>之后编译运行功能包</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>colcon build --packages-select myrobot![](https://www.yahboom.com/public/upload/upload-html/1757401978/image-20250905190216658.png)</span></span></code></pre></div><ul><li>刷新环境变量然后运行launch启动文件</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch myrobot bringup_model.launch.py</span></span></code></pre></div><img src="https://www.yahboom.com/public/upload/upload-html/1757401978/image-20250905190401459.png" alt="image-20250905190401459" style="zoom:33%;"><p>启动之后可以看到如下的Gazebo模型：</p><img src="https://www.yahboom.com/public/upload/upload-html/1757401978/image-20250905190451228.png" alt="image-20250905190451228" style="zoom:33%;"><p>可以看到红色的模型，因为最后加上了Gazebo的标签设置。</p>`,360)])])}const P=s(k,[["render",y]]);export{R as __pageData,P as default};
